h,w=19,16
g=[[4]*w for _ in range(h)]
ones=[(2,2),(4,14),(10,10),(17,9)]
sixes=[(4,4),(6,6),(7,14),(15,2)]
for r,c in ones:g[r][c]=1
for r,c in sixes:g[r][c]=6
# connect collinear 1s slope +/- 1
for i,(r,c) in enumerate(ones):
 for rr,cc in ones[i+1:]:
  if abs(rr-r)==abs(cc-c):
   dr=1 if rr>r else -1; dc=1 if cc>c else -1
   for k in range(abs(rr-r)+1):
    if g[r+dr*k][c+dc*k]!=6:g[r+dr*k][c+dc*k]=1
# extend sixes only if on a connecting one segment, along perpendicular diagonal
for sr,sc in sixes:
 if any(abs(sr-r)==abs(sc-c) and min(r,rr)<=sr<=max(r,rr) and min(c,cc)<=sc<=max(c,cc)
        and (sr-r)==(sc-c) for i,(r,c) in enumerate(ones) for rr,cc in ones[i+1:]):
  # line perpendicular: anti diagonal constant sum
  for r in range(h):
   c=sr+sc-r
   if 0<=c<w and g[r][c]!=1: g[r][c]=6
print(g)
print('\n'.join(' '.join(map(str,row)) for row in g))
